import{z as A,x as o,o as l,c as d,q as r,j as s,D as E,d as n,s as i,S as t,b as e}from"./chunks/framework.C8m1ZpeB.js";const u=JSON.parse('{"title":"损失厌恶与参考点","description":"","frontmatter":{"title":"损失厌恶与参考点","date":"2026-09-08T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/loss-aversion-reference.md","filePath":"econ/loss-aversion-reference.md","lastUpdated":1791063341000}'),p={name:"econ/loss-aversion-reference.md"};function m(b,a,T,c,h,D){const B=o("Mermaid");return l(),d("div",null,[a[2]||(a[2]=r('<h1 id="损失厌恶与参考点" tabindex="-1">损失厌恶与参考点 <a class="header-anchor" href="#损失厌恶与参考点" aria-label="Permalink to &quot;损失厌恶与参考点&quot;">​</a></h1><div class="epigraph"><p>损失的痛苦大于同等收益的快乐；没有参考点，这句话没有单位。</p><footer>—— Tversky and Kahneman, Loss Aversion in Riskless Choice: A Reference-Dependent Model, QJE 1991；对照 Kőszegi and Rabin, QJE 2006</footer></div><p><a href="/econ/prospect-theory">上一课</a>同时引入 \\(v\\) 与 \\(\\pi\\)。本课只拆损失厌恶：参考点两侧斜率不同，\\(\\lambda\\gt 1\\)。不重写权重函数。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>1979 年的 \\(v\\) 在零点拐折，损失段更陡。Tversky 与 Kahneman（1991）把同一逻辑写进无风险选择：买价与卖价缺口、现状偏误，不必有概率。参考点通常是现状、期望或刚实现的价格。Kőszegi 与 Rabin（2006）让参考点等于对结果的理性预期：人同时消费「消费效用」与「得-失效用」，均衡要求预期与选择一致。缺口是把拐折从实验室彩票接到状态依存的参考，而不是再推 <a href="/econ/expected-utility">vNM</a>。</p><p>家庭金融接口：股票相对买入价被编码成浮盈/浮亏，处置效应后课再写；本课只钉 \\(\\lambda\\) 与参考点的定义。</p><p><span class="marginnote">损失厌恶不是风险厌恶。\\(\\lambda\\) 比较的是参考点两侧的斜率；\\(\\gamma\\) 比较的是财富上 \\(u\\) 的弯曲。Benartzi–Thaler 的短视损失厌恶把两者乘在评价频率上，那是定价课。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>写 \\(v(x)=x\\)（收益）与 \\(v(x)=\\lambda x\\)（损失，\\(x\\lt 0\\)），或对凹/凸形状再加弯曲。风险中性加损失厌恶已经足以产生对小赌注的拒绝——Rabin 校准指出，vNM 若拒绝小赌注会推出对大赌注的荒谬拒绝；损失厌恶避开这条。参考点的选取：现状、买入价、KR 预期。本课不估计 \\(\\lambda\\approx 2\\) 的来源实验细节。</p><p><span class="marginnote">数字实例：\\(\\lambda\\approx 2\\) 意味着丢 100 元的痛约等于捡到 200 元的乐。于是「50% 概率赢 100、50% 概率输 100」的公平硬币在心理账上约值 \\(0.5\\times 100-0.5\\times 200=-50\\)，评价为负——人拒绝它完全不需要效用函数有任何弯曲。</span></p>',10)),(l(),s(t,null,{default:E(()=>[i(B,{id:"mermaid-28",class:"mermaid",graph:"flowchart%20TD%0A%20%20PT%5B%22%E5%89%8D%E6%99%AF%3A%20v%20%E5%9C%A8%E9%9B%B6%E7%82%B9%E6%8B%90%E6%8A%98%22%5D%20--%3E%20LA%5B%22%E6%8D%9F%E5%A4%B1%E5%8E%8C%E6%81%B6%20lambda%22%5D%0A%20%20LA%20--%3E%20STAT%5B%22%E5%8F%82%E8%80%83%E7%82%B9%3A%20%E7%8E%B0%E7%8A%B6%E6%88%96%E4%B9%B0%E5%85%A5%E4%BB%B7%22%5D%0A%20%20LA%20--%3E%20KR%5B%22Koszegi-Rabin%3A%20%E9%A2%84%E6%9C%9F%E5%8D%B3%E5%8F%82%E8%80%83%22%5D%0A%20%20LA%20--%3E%20ENDW%5B%22%E5%90%8E%E8%AF%BE%3A%20%E7%A6%80%E8%B5%8B%E6%95%88%E5%BA%94%22%5D%0A"})]),fallback:E(()=>[...a[0]||(a[0]=[n(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=e("h2",{id:"机制",tabindex:"-1"},[n("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=e("p",null,"机制是不对称编码。从参考点向上走一单位，价值增 \\(1\\)；向下走一单位，价值减 \\(\\lambda\\)。因此放弃已持有的物品被编码为损失，获得未持有的物品被编码为收益，WTA–WTP 缺口出现——禀赋效应课展开。在风险上，相对参考点的对称赌注期望为负（若 \\(\\lambda\\gt 1\\)），人拒绝公平硬币，看起来像极度厌恶风险。",-1)),a[5]||(a[5]=e("p",null,[e("span",{class:"marginnote"},"直觉类比：参考点像体重秤的归零钮——同样称出 5 公斤，从空秤上读是「白得」，从负位抬回来读是「还债」。得失的符号与轻重都取决于「从哪算起」，所以选参考点比选 \\(\\lambda\\) 的数值更能改变预测。")],-1)),(l(),s(t,null,{default:E(()=>[i(B,{id:"mermaid-38",class:"mermaid",graph:"flowchart%20TD%0A%20%20RP%5B%22%E5%8F%82%E8%80%83%E7%82%B9%3A%20%E7%8E%B0%E7%8A%B6%20%2F%20%E4%B9%B0%E5%85%A5%E4%BB%B7%20%2F%20%E7%90%86%E6%80%A7%E9%A2%84%E6%9C%9F%22%5D%20--%3E%20GAIN%5B%22%E9%AB%98%E5%87%BA%E5%8F%82%E8%80%83%E7%82%B9%3A%20%E7%BC%96%E7%A0%81%E4%B8%BA%E6%94%B6%E7%9B%8A%2C%20%E6%96%9C%E7%8E%87%201%22%5D%0A%20%20RP%20--%3E%20LOSS%5B%22%E4%BD%8E%E4%BA%8E%E5%8F%82%E8%80%83%E7%82%B9%3A%20%E7%BC%96%E7%A0%81%E4%B8%BA%E6%8D%9F%E5%A4%B1%2C%20%E6%96%9C%E7%8E%87%20lambda%22%5D%0A%20%20LOSS%20--%3E%20STEEP%5B%22lambda%20%E5%A4%A7%E4%BA%8E%201%3A%20%E4%B8%8B%E5%9D%A1%E6%9B%B4%E9%99%A1%22%5D%0A%20%20GAIN%20--%3E%20FAIR%5B%22%E5%AF%B9%E7%A7%B0%E5%85%AC%E5%B9%B3%E8%B5%8C%E6%B3%A8%3A%20%E5%BE%97%E7%9A%84%E5%BF%AB%E4%B9%90%E6%8A%B5%E4%B8%8D%E8%BF%87%E5%A4%B1%E7%9A%84%E7%97%9B%22%5D%0A%20%20STEEP%20--%3E%20FAIR%0A%20%20FAIR%20--%3E%20REJECT%5B%22%E6%8B%92%E7%BB%9D%E5%B0%8F%E8%B5%8C%E6%B3%A8%2C%20%E4%B8%8D%E5%BF%85%E5%81%87%E8%AE%BE%20u%20%E5%87%B9%22%5D%0A%20%20REJECT%20--%3E%20ENDO%5B%22%E6%8B%A5%E6%9C%89%E5%90%8E%E6%9B%B4%E5%80%BC%E9%92%B1%3A%20WTA-WTP%20%E7%BC%BA%E5%8F%A3%22%5D%0A"})]),fallback:E(()=>[...a[1]||(a[1]=[n(" Loading... ",-1)])]),_:1})),a[6]||(a[6]=r('<p>参考点移动时，同一期末财富的评价翻转。这与指数贴现的时间不一致不同：这里甚至不必跨期，一期菜单改框架即可。</p><p>Rabin 校准的逻辑要写清：若 vNM 在小赌注上拒绝公平硬币，凹性会在大赌注上爆炸；损失厌恶把「拒绝小赌注」从曲率挪到拐折，大赌注仍可被接受。KR 的预期参考点使已预期的工资不产生得失，未预期的奖金才进入 \\(v\\)——这与现状参考点对工资刚性、对股票买入价的预测不同，后课按对象选用，不混成一个 \\(\\lambda\\)。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>并非所有 WTA–WTP 缺口都是 \\(\\lambda\\)：收入效应、实验经验（List 2003 的专业交易者）会缩小缺口。KR 的预期参考点使「意料中的损失」不那么痛，与现状参考点预测不同。本课不把宏观消费欧拉改成损失厌恶欧拉。</p><p><span class="marginnote">常见误区：初学者容易把 WTA–WTP 缺口全归给损失厌恶——收入效应、市场经验也会造出缺口（List 2003 的专业交易者缺口明显更小）。另外「意料之中的损失」在 KR 参考点下几乎不痛，与现状参考点的预测不同：解释之前先问参考点定在哪。</span></p><p>后课默认：损失厌恶是 \\(v\\) 在参考点的斜率比；概率扭曲是另一零件。</p><p>\\(\\lambda\\) 比较参考点两侧斜率，不是 \\(u\\) 的曲率；小赌注拒绝因此不必推出荒谬的大赌注厌恶。</p><p>KR 的预期参考点与现状参考点对工资、对买入价的预测不同，后课按对象选用。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>损失厌恶是参考点两侧斜率之比，不是 \\(u\\) 的曲率。</li><li>参考点可以是现状、成本或理性预期（KR）。</li><li>小赌注拒绝不必推出荒谬的大赌注厌恶。</li><li>禀赋效应是现状参考点的现场。</li><li>短视损失厌恶把评价频率留给定价课。</li><li>出处：Tversky and Kahneman, <em>QJE</em> 1991；Kőszegi and Rabin, <em>QJE</em> 2006。</li></ul>',10))])}const C=A(p,[["render",m]]);export{u as __pageData,C as default};
